// Parse Relay transaction email with enhanced audit fields
const email = $input.first().json;
const subject = email.subject || '';
const body = email.text || email.snippet || '';

// Extract amount from subject: "Card transaction: $45.00 at OpenAI"
const amountMatch = subject.match(/\$([0-9,]+\.?[0-9]*)/);
const amount = amountMatch ? parseFloat(amountMatch[1].replace(',', '')) : 0;

// Extract merchant from subject
let merchant = 'Unknown Merchant';
const merchantMatch = subject.match(/at\s+(.+?)(?:\s*$|\s+on)/i);
if (merchantMatch) {
  merchant = merchantMatch[1].trim();
} else {
  const altMatch = subject.match(/by\s+(.+?)(?:\s*$|\s+on)/i);
  if (altMatch) merchant = altMatch[1].trim();
}
merchant = merchant.replace(/[*#]+/g, '').trim();

// Extract date from body
let transactionDate = new Date().toISOString().split('T')[0];
const datePatterns = [
  /on\s+([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i,
  /Date:\s*([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i,
  /(\d{1,2}\/\d{1,2}\/\d{2,4})/,
  /([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i
];
for (const pattern of datePatterns) {
  const dateMatch = body.match(pattern) || subject.match(pattern);
  if (dateMatch) {
    try {
      const parsed = new Date(dateMatch[1]);
      if (!isNaN(parsed.getTime())) {
        transactionDate = parsed.toISOString().split('T')[0];
        break;
      }
    } catch (e) {}
  }
}

// Determine payment method (Card vs ACH)
const subjectLower = subject.toLowerCase();
const bodyLower = body.toLowerCase();
let paymentMethod = 'Company Card';
let cardLast4 = '';

if (subjectLower.includes('ach') || bodyLower.includes('ach transfer')) {
  paymentMethod = 'Company Account (ACH)';
  // Try to extract account last 4
  const achMatch = body.match(/account\s*(?:ending in\s*|\*+)(\d{4})/i);
  if (achMatch) cardLast4 = achMatch[1];
} else {
  // Extract card last 4 digits
  const cardMatch = body.match(/ending in (\d{4})/) || body.match(/\*{4}\s*(\d{4})/) || subject.match(/\*+(\d{4})/);
  cardLast4 = cardMatch ? cardMatch[1] : '';
}

// Try to parse location from merchant (common patterns)
let locationCity = '';
let locationState = '';
let venueType = '';

// Pattern: "Merchant Name - City, ST" or "Merchant Name City ST"
const locationPatterns = [
  /[,-]\s*([A-Za-z\s]+),?\s*([A-Z]{2})\s*$/,
  /\s+([A-Za-z]+)\s+([A-Z]{2})\s*$/
];
for (const pattern of locationPatterns) {
  const locMatch = merchant.match(pattern);
  if (locMatch) {
    locationCity = locMatch[1].trim();
    locationState = locMatch[2];
    // Clean location from merchant name
    merchant = merchant.replace(pattern, '').trim();
    break;
  }
}

// Detect venue type from merchant keywords
const venueKeywords = {
  'restaurant': 'Restaurant',
  'cafe': 'Cafe/Coffee Shop',
  'coffee': 'Cafe/Coffee Shop',
  'starbucks': 'Cafe/Coffee Shop',
  'hotel': 'Hotel',
  'inn': 'Hotel',
  'marriott': 'Hotel',
  'hilton': 'Hotel',
  'airport': 'Airport',
  'airlines': 'Airport',
  'office': 'Office/Coworking',
  'wework': 'Office/Coworking'
};
const merchantLower = merchant.toLowerCase();
for (const [keyword, type] of Object.entries(venueKeywords)) {
  if (merchantLower.includes(keyword)) {
    venueType = type;
    break;
  }
}

// Generate unique transaction ID
const timestamp = Date.now();
const transactionId = `relay_${cardLast4 || 'xxxx'}_${timestamp}`;

// Calculate validation deadline (24 hours from now)
const deadline = new Date();
deadline.setHours(deadline.getHours() + 24);
const validationDeadline = deadline.toISOString().split('T')[0];

return [{
  json: {
    amount,
    merchant,
    transactionDate,
    paymentMethod,
    cardLast4,
    locationCity,
    locationState,
    venueType,
    transactionId,
    validationDeadline,
    source: 'Relay',
    emailId: email.id,
    rawSubject: subject,
    rawBody: body.substring(0, 500)
  }
}];

