// Error handling
const error = $input.first();
const originalEmail = $('Gmail - Relay Emails').first()?.json || {};

return [{
  json: {
    errorMessage: error.message || 'Failed to parse transaction email',
    emailSubject: originalEmail.subject || 'Unknown',
    emailFrom: originalEmail.from || 'Unknown',
    timestamp: new Date().toISOString()
  }
}];

